import assert from 'node:assert/strict';

class FakeElement {
  constructor(tag) {
    this.tagName = tag;
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.textContent = '';
    this.disabled = false;
    this.listeners = {};
    this.classList = { toggle() {} };
  }

  append(child) {
    this.children.push(child);
  }

  addEventListener(type, handler) {
    (this.listeners[type] ??= []).push(handler);
  }

  setAttribute(name, value) {
    this.attributes[name] = value;
  }

  click() {
    for (const handler of this.listeners.click ?? []) handler();
  }
}

const elements = { board: new FakeElement('div'), status: new FakeElement('p') };
globalThis.document = {
  getElementById: (id) => elements[id],
  createElement: (tag) => new FakeElement(tag),
};

await import('/Users/leonchan/WorkSpace/IDX-Tic-Tac-Toe/src/ui.js');

const cells = elements.board.children;
assert.equal(cells.length, 9);
assert.equal(elements.status.textContent, 'X to move');
assert.deepEqual(cells.map((c) => c.disabled), new Array(9).fill(false));

function play(sequence) {
  for (const cell of sequence) cells[cell].click();
}

// X line win on move 5.
play([0, 3, 1, 4, 2]);
assert.equal(elements.status.textContent, 'X wins with a line.');
assert.deepEqual(cells.map((c) => c.disabled), new Array(9).fill(true));
assert.equal(cells[2].textContent, 'X');
assert.equal(cells[4].textContent, 'O');

const frozen = cells[5].textContent;
cells[5].click();
assert.equal(cells[5].textContent, frozen, 'terminal click must not act');
assert.equal(elements.status.textContent, 'X wins with a line.');

// Fresh page state: fill win to O.
delete globalThis.document;
const freshElements = { board: new FakeElement('div'), status: new FakeElement('p') };
globalThis.document = {
  getElementById: (id) => freshElements[id],
  createElement: (tag) => new FakeElement(tag),
};
const url = `/Users/leonchan/WorkSpace/IDX-Tic-Tac-Toe/src/ui.js?fresh=${Date.now()}`;
await import(url);
const freshCells = freshElements.board.children;
play = (sequence) => {
  for (const cell of sequence) freshCells[cell].click();
};

play([0, 2, 1, 3, 4, 7, 5, 8, 6]);
assert.equal(freshElements.status.textContent, 'O wins: the board filled with no line.');
assert.deepEqual(freshCells.map((c) => c.disabled), new Array(9).fill(true));
freshCells[0].click();
assert.equal(freshElements.status.textContent, 'O wins: the board filled with no line.');

console.log('UI smoke OK: initial turn, line ending, fill ending, terminal clicks ignored');

